import requests
import json
import sys

video_ids = ["ZGdXAoVWF", "ZGdXDAmJY", "ZGdXAKBsq", "ZGdXD8or8", "ZGdXDSKoD", "ZGdXDNavu", "ZGdXDkuoT", "ZGdXDNret"]

headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.5",
}

results = []

for vid in video_ids:
    url = f"https://vm.tiktok.com/{vid}/"
    try:
        r = requests.get(url, headers=headers, timeout=15, allow_redirects=True)
        results.append({
            "video_id": vid,
            "status": r.status_code,
            "final_url": r.url,
            "content_length": len(r.text),
            "success": r.status_code == 200 and "tiktok.com" in r.url
        })
    except requests.Timeout:
        results.append({"video_id": vid, "status": "timeout", "success": False})
    except Exception as e:
        results.append({"video_id": vid, "status": "error", "error": str(e), "success": False})

print(json.dumps(results, indent=2))

import requests
import re
import json

video_ids = ["ZGdXAoVWF", "ZGdXDAmJY", "ZGdXAKBsq", "ZGdXD8or8", "ZGdXDSKoD", "ZGdXDNavu", "ZGdXDkuoT", "ZGdXDNret"]

headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.5",
}

results = []

for vid in video_ids:
    url = f"https://vm.tiktok.com/{vid}/"
    try:
        r = requests.get(url, headers=headers, timeout=15, allow_redirects=True)

        # TikTok speichert Metadaten als JSON im HTML
        data = {"video_id": vid, "final_url": r.url}

        # Versuche SIGI_STATE oder SIGI zu finden
        for pattern in [r'SIGI_STATE\s*=\s*({.*?});', r'SIGI\s*=\s*({.*?});']:
            m = re.search(pattern, r.text)
            if m:
                try:
                    sigi = json.loads(m.group(1))
                    # Navigiere zur Videoinfo
                    item_list = sigi.get("itemList", [])
                    if item_list:
                        item = item_list[0]
                        desc = item.get("desc", "")
                        author = item.get("author", {}).get("uniqueId", "")
                        stats = item.get("stats", {})
                        data["title"] = desc
                        data["author"] = author
                        data["stats"] = {
                            "diggCount": stats.get("diggCount", "?"),
                            "shareCount": stats.get("shareCount", "?"),
                            "commentCount": stats.get("commentCount", "?"),
                            "playCount": stats.get("playCount", "?"),
                        }
                    break
                except:
                    pass

        # Fallback: Meta-Tags
        if "title" not in data:
            m = re.search(r'<title[^>]*>([^<]+)</title>', r.text)
            if m:
                data["title"] = m.group(1)

        # Prüfe ob es ein Photo-Post ist
        if "/photo/" in r.url:
            data["type"] = "photo"
        else:
            data["type"] = "video"

        results.append(data)
    except Exception as e:
        results.append({"video_id": vid, "error": str(e)})

print(json.dumps(results, indent=2, ensure_ascii=False))

