import requests
import re
import json
from html import unescape

video_ids = ["ZGdXAoVWF", "ZGdXDAmJY", "ZGdXAKBsq", "ZGdXD8or8", "ZGdXDSKoD", "ZGdXDNavu", "ZGdXDkuoT", "ZGdXDNret"]

headers = {
    "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36",
    "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
    "Accept-Language": "en-US,en;q=0.5",
}

results = []

for vid in video_ids:
    url = f"https://vm.tiktok.com/{vid}/"
    try:
        r = requests.get(url, headers=headers, timeout=15, allow_redirects=True)

        data = {"video_id": vid, "final_url": r.url}

        # Suche nach JSON-LD (VideoObject)
        m = re.search(r'<script[^>]*type=["\']application/ld\+json["\'][^>]*>(.*?)</script>', r.text, re.DOTALL)
        if m:
            try:
                ld_json = json.loads(m.group(1))
                if isinstance(ld_json, dict):
                    data["title"] = ld_json.get("name", "")
                    data["description"] = ld_json.get("description", "")
                    data["author"] = ld_json.get("author", {}).get("name", "") if isinstance(ld_json.get("author"), dict) else ""
            except:
                pass

        # Fallback: Suche nach "desc":" im HTML
        if "title" not in data:
            m = re.search(r'"desc":"([^"]+)"', r.text)
            if m:
                data["title"] = unescape(m.group(1).replace('\\/', '/'))

        # Author aus URL extrahieren
        author_match = re.search(r'tiktok\.com/@([^/]+)', r.url)
        if author_match:
            data["author"] = author_match.group(1)

        # Typ bestimmen
        data["type"] = "photo" if "/photo/" in r.url else "video"

        results.append(data)
    except Exception as e:
        results.append({"video_id": vid, "error": str(e)})

print(json.dumps(results, indent=2, ensure_ascii=False))

