425:   let text = String(m.text || '').trim();
426:   if (!text && mediaResult && captionText) {
427:     // Caption als Ersatz für fehlenden Text nutzen
428:     text = captionText;
429:   } else if (captionText) {
430:     // Caption anhängen falls Text vorhanden ist
431:     text = text ? text + '\n---\n' + captionText : captionText;
432:   }
433:   if (!text) return;
434:   if (text.length > 4000) text = text.slice(0, 4000) + ' …(gekürzt)';
435: 
436:   const lower = text.toLowerCase();
437:   if (lower === '/status' || lower === '/status@dirkb_bot') {
438:     const c = counts();
439:     let out = `Status v4: wartend ${c.queued}, läuft ${c.running}, fertig ${c.done}, fehlgeschlagen ${c.failed}.`;
440:     const runningJobs = state.jobs.filter(j => j.status === 'running');
441:     if (runningJobs.length) {
442:       out += `\nAktive Jobs:`;
443:       for (const j of runningJobs) {
444:         const since = j.startedAt ? new Date(j.startedAt).toLocaleTimeString('de-DE') : '?';
445:         out += `\n- @${j.route} seit ${since}: ${String(j.text || '').slice(0, 100)}`;
446:       }
447:     } else {
448:       out += `\nAktive Jobs: –`;
449:     }
450:     const sessionKeys = Object.keys(state.sessions || {});
451:     if (sessionKeys.length) {
452:       out += `\nSessions: ${sessionKeys.map(r => `${r}=${String(state.sessions[r] || '').slice(0, 8)}`).join(' | ')}`;
453:     }
454:     deliver(chatId, out);
455:     return;
456:   }
457:   if (lower === '/help' || lower === '/start') {
458:     deliver(chatId, 'Schick mir einfach einen Auftrag – ich leite ihn an opencode weiter und antworte dir.\n@route Meldung steer auf diese Route (z.B. @social …)\n/status – Job-Übersicht\n/id – zeigt deine Chat-ID');
459:     return;
460:   }
461:   if (lower === '/id') { deliver(chatId, 'Deine Chat-ID: ' + chatId); return; }
462: 
463:   // "@route Name" steuert die Ziel-Route
464:   let route = 'default';
465:   const match = /^@([a-z0-9-]+)\s+([\s\S]+)/.exec(text);
466:   if (match && CFG.routes[match[1]]) { route = match[1]; text = match[2].trim(); }
467: 
468:   enqueue({ text, route, from: String(chatId), channel: 'telegram', chatId, replyTo: m.message_id });
469:   tgApi('sendChatAction', { chat_id: chatId, action: 'typing' }, 8000).catch(() => {});
