472: async function telegramCycle() {
473:   const updates = await tgApi('getUpdates',
474:     { offset: state.offset, timeout: CFG.telegramPollTimeoutSec || 25, allowed_updates: ['message'] },
475:     ((CFG.telegramPollTimeoutSec || 25) + 15) * 1000);
476:   if (conflictStrikes) { conflictStrikes = 0; lastTelegramError = ''; log('Telegram-Konflikt behoben'); }
477:   for (const u of updates) {
478:     state.offset = u.update_id + 1;
479:     if (u.message) handleIncoming(u.message.chat ? Number(u.message.chat.id) : 0, u.message);
480:   }
481:   saveState();
482: }
