484: let webhookCleanupIssued = false;
485: async function pollLoop() {
486:   pollerAlive = true;
487:   while (pollerAlive) {
488:     try {
489:       await telegramCycle();
490:     } catch (e) {
491:       const desc = String(e.description || e.message || '');
492:       lastTelegramError = desc.slice(0, 200);
493:       if (/webhook/i.test(desc)) {
494:         log('409: webhook aktiv – lösche Webhook bei Telegram und fahre fort.');
495:         try { await tgApi('deleteWebhook', { drop_pending_updates: false }, 15000); lastTelegramError = ''; } catch (e2) { log('deleteWebhook-Fail', e2.message); }
496:         continue;
497:       }
498:       if (/409|conflict/i.test(desc)) {
499:         conflictStrikes++;
500:         log('getUpdates-Konflikt', conflictStrikes, desc.slice(0, 120));
501:         if (conflictStrikes >= 3) { pollerAlive = false; log('ERROR: Poller gestoppt – ein anderer getUpdates-Konsument ist aktiv. Nur EINE Instanz starten!'); continue; }
502:         await sleep(5000); continue;
503:       }
504:       log('poll-error', lastTelegramError); await sleep(4000);
505:     }
506:   }
507:   lastTelegramError = lastTelegramError || 'Poller gestoppt';
508: }
