510: // ---------------- opencode Runner ----------------
511: function runOpencode(job) {
512:   return new Promise((resolve, reject) => {
513:     const routeDef = CFG.routes[job.route] || CFG.routes.default;
514:     const dirAbs = path.isAbsolute(routeDef.dir) ? routeDef.dir : path.join(CFG.workspace, routeDef.dir || '.');
515:     const cwd = fs.existsSync(dirAbs) ? dirAbs : CFG.workspace;
516:     const session = state.sessions[job.route] || '';
517: 
518:     const args = ['run', '--format', 'json'];
519:     if (CFG.opencode?.auto !== false) args.push('--auto');
520:     if (routeDef.model) args.push('--model', routeDef.model);
521:     if (session) args.push('--session', session);
522:     args.push('--title', String(job.text || '').slice(0, 60) || 'AI-SYSTEM');
523:     args.push(String(job.text || ''));
524: 
525:     const child = spawn(CFG.opencodeExe, args, {
526:       cwd, windowsHide: true, stdio: ['ignore', 'pipe', 'pipe'],
527:       env: { ...process.env, OPENCODE_CONFIG: CFG.opencodeConfig }
528:     });
529: 
530:     let settled = false, stdout = '', stderr = '';
531:     const tokens = setTimeout(() => {
532:       if (settled) return; settled = true;
533:       try { spawn('taskkill', ['/PID', String(child.pid), '/T', '/F'], { windowsHide: true }); } catch { child.kill('SIGKILL'); }
534:       reject(new Error(`opencode Timeout nach ${CFG.routeTimeoutSec}s`));
535:     }, (CFG.routeTimeoutSec || 900) * 1000);
536:     child.unref?.();
537: 
538:     child.stdout.on('data', d => stdout += d);
539:     child.stderr.on('data', d => stderr += d);
540:     child.on('error', e => { if (settled) return; settled = true; clearTimeout(tokens); reject(e); });
541:     child.on('close', code => {
542:       if (settled) return; settled = true; clearTimeout(tokens);
543:       let newSession = '', texts = [];
544:       for (const line of stdout.split(/\r?\n/)) {
545:         const l = line.trim();
546:         if (!l.startsWith('{')) continue;
547:         try {
548:           const ev = JSON.parse(l);
549:           if (ev.sessionID && !newSession) newSession = String(ev.sessionID);
550:           if (ev.type === 'text' && ev.part && typeof ev.part.text === 'string') texts.push(ev.part.text);
551:         } catch { /* kein json */ }
552:       }
553:       if (newSession) state.sessions[job.route] = newSession;
554:       const answer = texts.join('').trim();
555:       if (code !== 0) { reject(new Error(`opencode exit ${code}: ${(stderr || stdout).slice(0, 300)}`)); return; }
556:       if (!answer) { reject(new Error('opencode lieferte keinen Text (' + stdout.trim().slice(0, 160) + ')')); return; }
557:       resolve(answer);
558:     });
559:   });
560: }
