562: async function workerLoop() {
563:   for (;;) {
564:     const job = state.jobs.find(j => j.status === 'queued');
565:     if (!job) { await sleep(800); continue; }
566:     job.status = 'running'; job.startedAt = Date.now(); saveState();
567:     log('Job gestartet', job.id.slice(0, 8), '@' + job.route, 'channel', job.channel);
568:     try {
569:       const answer = await runOpencode(job);
570:       job.status = 'done'; job.answer = answer.slice(0, 8000); job.finishedAt = Date.now();
571:       log('Job fertig', job.id.slice(0, 8));
572:       if (job.notify) await deliver(job.chatId, answer, job.replyTo);
573:     } catch (e) {
574:       const errMsg = String(e && (e.message || e) || '').slice(0, 1200);
575:       if (isContextOverflowError(errMsg)) {
576:         saveHandoff(job, 'context_overflow', errMsg);
577:         delete state.sessions[job.route];
578:         state.msgCounts[job.route] = 0;
579:         job.status = 'failed'; job.error = 'Kontextlimit erreicht - Stand gespeichert, neuer Versuch in frischer Session.'; job.finishedAt = Date.now();
580:         const prev = (state.handoffs && state.handoffs[job.route]) ? ('\n\n--- Gesicherter Stand (automatisch) ---\n' + state.handoffs[job.route].slice(0, 2500)) : '';
581:         const retryJob = enqueue({ text: 'Führe die Aufgabe in einer frischen Session fort. Nutze den gesicherten Stand und arbeite automatisch weiter.\n\nUrsprünglicher Auftrag:\n' + String(job.text || '').slice(0, 3000) + prev, route: job.route, from: job.from || 'system', channel: job.channel || 'system', chatId: job.chatId, replyTo: job.replyTo });
582:         if (job.notify) await deliver(job.chatId, '⚠️ Chat war zu groß/413. Stand wurde gespeichert, ich starte automatisch in einer frischen Session weiter (Job ' + retryJob.id.slice(0,8) + ').', job.replyTo);
583:         log('Auto-Weiterarbeit nach Kontextlimit', job.id.slice(0,8), '->', retryJob.id.slice(0,8));
584:       } else {
585:         job.status = 'failed'; job.error = errMsg.slice(0, 400); job.finishedAt = Date.now();
586:         log('Job FEHLGESCHLAGEN', job.id.slice(0, 8), job.error);
587:         if (job.notify) await deliver(job.chatId, '❌ Fehler: ' + job.error, job.replyTo);
588:         delete state.sessions[job.route];
589:       }
590:     }
591:     bumpMsgCount(job.route);
592:     saveState();
593:   }
594: }
