596: // ---------------- HTTP (PWA-API) ----------------
597: const MIME = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.mjs': 'text/javascript; charset=utf-8', '.json': 'application/json; charset=utf-8', '.webmanifest': 'application/manifest+json; charset=utf-8', '.png': 'image/png', '.svg': 'image/svg+xml', '.css': 'text/css; charset=utf-8', '.ico': 'image/x-icon' };
598: 
599: function sendJson(res, code, obj) {
600:   const body = JSON.stringify(obj);
601:   res.writeHead(code, { 'Content-Type': 'application/json; charset=utf-8', 'Content-Length': Buffer.byteLength(body), 'Cache-Control': 'no-store' });
602:   res.end(body);
603: }
604: 
605: function serveStatic(res, urlPath) {
606:   const rel = urlPath === '/' ? '/index.html' : urlPath.split('?')[0];
607:   const file = path.normalize(path.join(PUBLIC, rel));
608:   if (!file.startsWith(PUBLIC)) { res.writeHead(404); res.end('not found'); return; }
609:   fs.readFile(file, (err, data) => {
610:     if (err) { res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' }); res.end('not found'); return; }
611:     res.writeHead(200, { 'Content-Type': MIME[path.extname(file)] || 'application/octet-stream', 'Cache-Control': path.extname(file) === '.html' ? 'no-store' : 'max-age=3600' });
612:     res.end(data);
613:   });
614: }
