616: const httpServer = http.createServer((req, res) => {
617:   const url = (req.url || '/').split('?')[0];
618:   if (url === '/health') {
619:     return sendJson(res, 200, {
620:       status: 'ok',
621:       service: 'ai-system-v4',
622:       uptimeSec: Math.round(process.uptime()),
623:       memory: { rss: process.memoryUsage().rss },
624:       telegram: TELEGRAM_ENABLED ? 'connected' : 'disabled',
625:       timestamp: new Date().toISOString()
626:     });
627:   }
628:   if (url === '/api/status') {
629:     return sendJson(res, 200, {
630:       ok: true, v4: true, root: ROOT, uptimeSec: Math.round(process.uptime()),
631:       telegram: { enabled: TELEGRAM_ENABLED, running: pollerAlive, lastError: lastTelegramError },
632:       queue: counts()
633:     });
634:   }
635:   if (url === '/api/jobs' && req.method === 'GET') {
636:     return sendJson(res, 200, { fetchedAt: Date.now(), counts: counts(), jobs: state.jobs.slice(-50).reverse() });
637:   }
638:   if (url === '/api/jobs' && req.method === 'POST') {
639:     let body = '';
640:     req.on('data', c => { body += c; if (body.length > 16000) req.destroy(); });
641:     req.on('end', () => {
642:       try {
643:         const input = JSON.parse(body || '{}');
644:         const text = String(input.text || '').trim();
645:         if (!text) return sendJson(res, 400, { ok: false, error: 'text fehlt' });
646:         if (text.length > 4000) return sendJson(res, 400, { ok: false, error: 'text zu lang (max 4000)' });
647:         const route = CFG.routes[input.route] ? input.route : 'default';
648:         const job = enqueue({ text, route, from: 'pwa', channel: 'pwa', chatId: null, replyTo: null });
649:         return sendJson(res, 200, { ok: true, id: job.id, route: job.route });
650:       } catch (e) { return sendJson(res, 400, { ok: false, error: String(e.message || e) }); }
651:     });
652:     return;
653:   }
654:   serveStatic(res, url);
655: });
